(()=>{const menu=document.querySelector('.menu-toggle'),nav=document.querySelector('#nav');menu.addEventListener('click',()=>{const open=nav.classList.toggle('open');menu.setAttribute('aria-expanded',String(open));menu.textContent=open?'Fechar −':'Menu +'});document.addEventListener('keydown',e=>{if(e.key==='Escape'){nav.classList.remove('open');menu.setAttribute('aria-expanded','false');menu.textContent='Menu +'}});const tabs=[...document.querySelectorAll('[data-panel]')];tabs.forEach((tab,i)=>{tab.addEventListener('click',()=>{tabs.forEach(b=>{const selected=b===tab;b.setAttribute('aria-selected',String(selected));document.getElementById(b.dataset.panel).hidden=!selected})});tab.addEventListener('keydown',e=>{if(['ArrowLeft','ArrowRight'].includes(e.key)){e.preventDefault();const next=tabs[(i+1)%tabs.length];next.focus();next.click()}})});const home=document.querySelector('.home');if(home&&!matchMedia('(prefers-reduced-motion: reduce)').matches&&matchMedia('(pointer:fine)').matches){home.addEventListener('pointermove',e=>{const r=home.getBoundingClientRect(),x=(e.clientX-r.left)/r.width-.5,y=(e.clientY-r.top)/r.height-.5;home.style.setProperty('--px',x*20+'px');home.style.setProperty('--py',y*10+'px');home.style.setProperty('--rot',x+'deg')},{passive:true});home.addEventListener('pointerleave',()=>['--px','--py','--rot'].forEach(p=>home.style.removeProperty(p)))}const service=new URLSearchParams(location.search).get('servico');if(service)document.querySelectorAll('[name=service]').forEach(r=>r.checked=r.value===service)})();
(()=>{const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;if(reduced)return;const observer=new IntersectionObserver(entries=>entries.forEach(entry=>{if(!entry.isIntersecting)return;const el=entry.target;el.animate([{opacity:.25,transform:'translateY(38px)',clipPath:'inset(0 0 9% 0)'},{opacity:1,transform:'translateY(0)',clipPath:'inset(0)'}],{duration:1100,easing:'cubic-bezier(.16,1,.3,1)',fill:'none'});observer.unobserve(el)}),{threshold:.12});document.querySelectorAll('[data-reveal]').forEach(el=>observer.observe(el));const hero=document.querySelector('.editorial .home');if(hero){const sequence=[['h1',0],['.lead',180],['.hero-actions',300],['.portrait img',100],['.portrait-tag',480]];sequence.forEach(([sel,delay])=>{const el=hero.querySelector(sel);el.animate([{opacity:0,translate:'0 30px',clipPath:'inset(0 0 18% 0)'},{opacity:1,translate:'0 0',clipPath:'inset(0)'}],{duration:1400,delay,easing:'cubic-bezier(.16,1,.3,1)',fill:'backwards'})})}const story=document.querySelector('.service-story');if(story){let scheduled=false;function draw(){const rect=story.getBoundingClientRect();const progress=Math.max(0,Math.min(1,(innerHeight*.65-rect.top)/(rect.height-innerHeight*.2)));story.style.setProperty('--chapter',progress.toFixed(3));scheduled=false}addEventListener('scroll',()=>{if(!scheduled){scheduled=true;requestAnimationFrame(draw)}},{passive:true});addEventListener('resize',draw);draw()}if(matchMedia('(pointer:fine)').matches)document.querySelectorAll('.editorial .button').forEach(button=>{button.addEventListener('pointermove',e=>{const box=button.getBoundingClientRect();button.style.translate=((e.clientX-box.left-box.width/2)*.09)+'px '+((e.clientY-box.top-box.height/2)*.12)+'px'});button.addEventListener('pointerleave',()=>button.style.translate='0 0')})})();

